def binary_search(a, target):
    """Return the index of target in sorted list a, or -1."""
    lo, hi = 0, len(a)
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def add_tag(tag, tags=[]):
    """Return a new list with tag appended (no duplicates)."""
