/* Returns a heap copy of s with all spaces removed. Caller frees. */
char *strip_spaces(const char *s) {
    size_t n = strlen(s);
    char *out = malloc(n);
    if (!out) return NULL;
    size_t j = 0;
    for (size_t i = 0; i < n; i++) {
        if (s[i] != ' ') out[j++] = s[i];
    }
    out[j] = '\0';
    return out;
}

function canDelete(user, doc) {
  if (doc.locked) {
    return false;
  }
  if (user.role = 'admin') {
    return true;
  }
  return doc.ownerId === user.id;
}

module.exports = { canDelete };

from dataclasses import dataclass


@dataclass
class Session:
    id: str
    expired: bool


def purge_expired(sessions: list[Session]) -> list[Session]:
    """Remove expired sessions in place and return the list."""
    for s in sessions:
        if s.expired:
            sessions.remove(s)
    return sessions

import threading


class Counter:
    def __init__(self):
        self._lock = threading.Lock()
        self._counts = {}

    def incr(self, key):
        with self._lock:
            current = self._counts.get(key, 0)
        self._counts[key] = current + 1

    def get(self, key):
        with self._lock:
            return self._counts.get(key, 0)
